import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { DevServerState } from '../DevServerState.js';
import * as proxyService from '../proxy/AppProxyService.js';
import startDevServer from '../server.js';
import * as serverlessServices from '../serverless/services/AppFunctionExecutionService.js';
import { createDevServerConfig, createMockLogger, createMockViteDevServer, } from './factories.js';
const useMock = vi.fn();
vi.mock('../serverless/services/AppFunctionExecutionService.ts', () => ({
    AppFunctionExecutionService: vi.fn(async () => vi.fn((req, res, next) => next())),
}));
vi.mock('../proxy/AppProxyService.ts', () => ({
    AppProxyService: vi.fn(() => vi.fn((req, res, next) => next())),
}));
vi.mock('express', () => {
    const expressMock = () => ({
        use: useMock,
        get: vi.fn(),
        listen: (__, callback) => {
            // simulate async listen
            const serverMock = {
                on: vi.fn(function (event) {
                    if (event === 'error') {
                        // Don't call error handler in tests
                    }
                    return this;
                }),
                close: vi.fn((cb) => cb && cb()),
            };
            setTimeout(callback, 1);
            return serverMock;
        },
    });
    expressMock.static = vi.fn(() => vi.fn());
    return { default: expressMock };
});
describe('server', () => {
    let logger;
    let devServerConfig;
    beforeEach(() => {
        logger = createMockLogger();
        devServerConfig = createDevServerConfig(logger);
    });
    afterEach(() => {
        vi.resetAllMocks();
    });
    describe('startDevServer', () => {
        beforeEach(() => {
            useMock.mockClear();
            vi.mocked(serverlessServices.AppFunctionExecutionService).mockResolvedValue(vi.fn());
            vi.mocked(proxyService.AppProxyService).mockReturnValue(vi.fn());
            vi.clearAllMocks();
        });
        it('should add the AppProxyService middleware when localDevUrlMapping is provided', async () => {
            const devServerState = new DevServerState({
                ...devServerConfig,
                localDevUrlMapping: {
                    'https://inbound.com': 'http://localhost',
                },
            });
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(useMock).toHaveBeenNthCalledWith(3, '/api/crm-extensibility/execution/internal/v3', expect.any(Function), 
            // This is the AppProxyService middleware
            expect.any(Function));
            expect(proxyService.AppProxyService).toHaveBeenCalledTimes(1);
            expect(proxyService.AppProxyService).toHaveBeenCalledWith({
                accountId: devServerConfig.accountId,
                allowedUrls: [],
                localDevUrlMapping: devServerState.localDevUrlMapping,
                logger: devServerState.logger,
            });
        });
        it('should not add the AppProxyService middleware when the localDevUrlMapping is empty', async () => {
            const devServerState = new DevServerState({
                ...devServerConfig,
                localDevUrlMapping: {},
            });
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(useMock).toHaveBeenNthCalledWith(3, '/api/crm-extensibility/execution/internal/v3', expect.any(Function));
            expect(proxyService.AppProxyService).toHaveBeenCalledTimes(0);
        });
        it('should not add the AppProxyService middleware when localDevUrlMapping is not provided', async () => {
            const devServerState = new DevServerState({
                ...devServerConfig,
                localDevUrlMapping: undefined,
            });
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(useMock).toHaveBeenNthCalledWith(3, '/api/crm-extensibility/execution/internal/v3', expect.any(Function));
            expect(proxyService.AppProxyService).toHaveBeenCalledTimes(0);
        });
        it('should add the AppFunctionExecutionService middleware if is a private app', async () => {
            const devServerState = new DevServerState({
                ...devServerConfig,
                localDevUrlMapping: {
                    'https://inbound.com': 'http://localhost',
                },
            });
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(serverlessServices.AppFunctionExecutionService).toHaveBeenCalledTimes(1);
        });
        it('should not add the AppFunctionExecutionService middleware if is a public app', async () => {
            const devServerState = new DevServerState({
                ...devServerConfig,
                appConfig: { isPublicApp: true },
                localDevUrlMapping: {
                    'https://inbound.com': 'http://localhost',
                },
            });
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(serverlessServices.AppFunctionExecutionService).not.toHaveBeenCalled();
        });
        it('should return httpServer and shutdown function', async () => {
            const devServerState = new DevServerState(devServerConfig);
            const result = await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(result).toHaveProperty('httpServer');
            expect(result).toHaveProperty('shutdown');
            expect(typeof result.shutdown).toBe('function');
        });
        it('should initialize ExtensionsWebSocket on devServerState', async () => {
            const devServerState = new DevServerState(devServerConfig);
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(devServerState.extensionsWebSocket).toBeDefined();
        });
        it('should broadcast shutdown messages before closing WebSocket', async () => {
            const devServerState = new DevServerState(devServerConfig);
            const { shutdown } = await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            const ws = devServerState.extensionsWebSocket;
            const callOrder = [];
            const broadcastSpy = vi.spyOn(ws, 'broadcast').mockImplementation(() => {
                callOrder.push('broadcast');
            });
            const closeSpy = vi.spyOn(ws, 'close').mockImplementation(async () => {
                callOrder.push('close');
            });
            await shutdown();
            expect(broadcastSpy).toHaveBeenCalledWith(expect.objectContaining({
                event: 'shutdown',
                version: 1,
            }));
            expect(closeSpy).toHaveBeenCalledOnce();
            expect(callOrder).toEqual(['broadcast', 'close']);
        });
        it('should trigger WebSocket setup after initialization', async () => {
            const triggerSpy = vi.spyOn(DevServerState.prototype, 'triggerWebSocketSetup');
            const devServerState = new DevServerState(devServerConfig);
            await startDevServer({
                devServerState,
                viteDevServer: createMockViteDevServer(),
            });
            expect(triggerSpy).toHaveBeenCalledTimes(1);
            triggerSpy.mockRestore();
        });
    });
});
